package rs.unicredit.cbr.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.CbrIngestRequest;
import rs.unicredit.cbr.dto.CbrStatItem;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.CbrTransactionStat;
import rs.unicredit.cbr.model.ParseStatus;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

@Service
@RequiredArgsConstructor
public class CbrIngestionService {

    private final CbrTransactionRepository transactionRepository;
    private final CbrTransactionRequestRepository requestRepository;

    @Transactional
    public CbrTransaction ingest(CbrIngestRequest input) {
        // 1) upisi raw request
        CbrTransactionRequest request = new CbrTransactionRequest();
        request.setSourceSystem(input.sourceSystem());
        request.setRawXml(input.rawXml());
        request.setParseStatus(ParseStatus.RECEIVED);
        request = requestRepository.save(request);

        // 2) napravi transakciju sa svim dostupnim parsiranim poljima
        CbrTransaction txn = new CbrTransaction();
        txn.setRequest(request);
        txn.setCallReplyRef(input.callReplyRef());
        txn.setMessageType(input.messageType());
        txn.setTransferMethod(input.transferMethod());
        txn.setDirection(input.direction());
        txn.setPaymentReference(input.paymentReference());
        txn.setOriginalTransactionId(input.originalTransactionId());
        txn.setOriginalChannelReference(input.originalChannelReference());
        txn.setSourceReceivedAt(input.sourceReceivedAt());
        txn.setSettlementAmount(input.settlementAmount());
        txn.setSettlementCurrency(input.settlementCurrency());
        txn.setOriginalSettlementAmount(input.originalSettlementAmount());
        txn.setOriginalSettlementCurrency(input.originalSettlementCurrency());
        txn.setSettlementDate(input.settlementDate());
        txn.setPaymentServiceLevel(input.paymentServiceLevel());
        txn.setPaymentLocalInstrument(input.paymentLocalInstrument());
        txn.setPaymentCategoryPurpose(input.paymentCategoryPurpose());
        txn.setOriginalPaymentType(input.originalPaymentType());
        txn.setDebtorAgent(input.debtorAgent());
        txn.setCreditorAgent(input.creditorAgent());
        txn.setDebtorIdBic(input.debtorIdBic());
        txn.setDebtorIdLei(input.debtorIdLei());
        txn.setDebtorIdOthr(input.debtorIdOthr());
        txn.setDebtorIdPrvtId(input.debtorIdPrvtid());
        txn.setCreditorIdBic(input.creditorIdBic());
        txn.setCreditorIdLei(input.creditorIdLei());
        txn.setCreditorIdOthr(input.creditorIdOthr());
        txn.setCreditorIdPrvtId(input.creditorIdPrvtid());
        txn.setDebtorName(input.debtorName());
        txn.setCreditorName(input.creditorName());
        txn.setDebtorIban(input.debtorIban());
        txn.setCreditorIban(input.creditorIban());
        txn.setDebtorAccountNo(input.debtorAccountNo());
        txn.setCreditorAccountNo(input.creditorAccountNo());
        txn.setDebtorPostalAddress(input.debtorPostalAddress());
        txn.setCreditorPostalAddress(input.creditorPostalAddress());
        txn.setDebtorResidency(input.debtorResidency());
        txn.setCreditorResidency(input.creditorResidency());
        txn.setChargeBearer(input.chargeBearer());
        txn.setRemittanceInfo(input.remittanceInfo());
        txn.setReportType(input.reportType());
        txn.setPaymentInstrument(input.paymentInstrument());
        txn.setSpecialMark(input.specialMark());
        txn.setCountryCode1(input.countryCode1());
        txn.setCountryCode2(input.countryCode2());
        txn.setLoanNumber(input.loanNumber());
        txn.setLoanYear(input.loanYear());
        txn.setDrStatisticalCode(input.drStatisticalCode());
        txn.setCrStatisticalCode(input.crStatisticalCode());

        // 3) upisi statisticke detalje ako postoje
        if (input.stats() != null && !input.stats().isEmpty()) {
            for (CbrStatItem item : input.stats()) {
                CbrTransactionStat stat = new CbrTransactionStat();
                stat.setTransaction(txn);
                stat.setStatDirection(item.statDirection());
                stat.setStatisticalCode(item.statisticalCode());
                stat.setSplitStatCode(item.splitStatCode());
                stat.setSplitAmount(item.splitAmount());
                stat.setSplitAmountCurrency(item.splitAmountCurrency());
                stat.setInvoiceNumber(item.invoiceNumber());
                stat.setInvoiceYear(item.invoiceYear());
                txn.getRegulatoryDetails().add(stat);
            }
        }

        return transactionRepository.save(txn);
    }
}

