import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jms.connection.CachingConnectionFactory;
import org.springframework.jms.core.JmsTemplate;

@Configuration
@EnableConfigurationProperties(MqProperties.class)
public class MqConfig {

    private static final Logger LOG = LoggerFactory.getLogger(MqConfig.class);

    @Bean
    @ConditionalOnProperty(prefix = "mq", name = "enabled", havingValue = "true")
    public MQConnectionFactory ibmMqConnectionFactory(MqProperties properties) throws JMSException {
        MQConnectionFactory factory = new MQConnectionFactory();
        factory.setTransportType(WMQConstants.WMQ_CM_CLIENT);
        factory.setHostName(properties.getHost());
        factory.setPort(properties.getPort());
        factory.setQueueManager(properties.getQueueManager());
        factory.setChannel(properties.getChannel());
        factory.setAppName(properties.getAppName());
        factory.setStringProperty(WMQConstants.USERID, properties.getUsername());
        factory.setStringProperty(WMQConstants.PASSWORD, properties.getPassword());
        factory.setBooleanProperty(WMQConstants.USER_AUTHENTICATION_MQCSP, true);
        if (properties.isUseTls() && properties.getCipherSuite() != null) {
            factory.setSSLCipherSuite(properties.getCipherSuite());
        }
        LOG.info("IBM MQ connection factory initialized for host {}:{} qm {}", properties.getHost(), properties.getPort(),
                properties.getQueueManager());
        return factory;
    }

    @Bean
    @ConditionalOnBean(MQConnectionFactory.class)
    public ConnectionFactory mqCachingConnectionFactory(MQConnectionFactory baseFactory) {
        CachingConnectionFactory cachingConnectionFactory = new CachingConnectionFactory(baseFactory);
        cachingConnectionFactory.setReconnectOnException(true);
        cachingConnectionFactory.setSessionCacheSize(5);
        return cachingConnectionFactory;
    }

    @Bean
    @ConditionalOnBean(ConnectionFactory.class)
    public JmsTemplate mqJmsTemplate(ConnectionFactory connectionFactory, MqProperties properties) {
        JmsTemplate jmsTemplate = new JmsTemplate(connectionFactory);
        jmsTemplate.setDefaultDestinationName(properties.getQueue());
        LOG.info("JMS template configured with default queue {}", properties.getQueue());
        return jmsTemplate;
    }
}

